<?php

use Yoast\PHPUnitPolyfills\TestCases\TestCase;

require_once 'Zend/Db/Adapter/Db2.php';
require_once 'Zend/Db/Adapter/Pdo/Ibm/Db2.php';

/**
 * SQL generated by limit() of the DB2 adapters, no database connection needed
 *
 * @group      Zend_Db
 * @group      Zend_Db_Adapter
 */
class Zend_Db_Adapter_Db2LimitTest extends TestCase
{
    /**
     * @return array
     */
    public static function limitProvider()
    {
        return [
            'first rows'   => [10, 0, 'SELECT * FROM t ORDER BY id FETCH FIRST 10 ROWS ONLY'],
            'with offset'  => [10, 20, 'SELECT * FROM t ORDER BY id OFFSET 20 ROWS FETCH FIRST 10 ROWS ONLY'],
            'string input' => ['5', '1', 'SELECT * FROM t ORDER BY id OFFSET 1 ROWS FETCH FIRST 5 ROWS ONLY'],
        ];
    }

    /**
     * @dataProvider limitProvider
     */
    public function testDb2Limit($count, $offset, $expected)
    {
        $this->assertSame($expected, $this->_getDb2Adapter()->limit('SELECT * FROM t ORDER BY id', $count, $offset));
    }

    /**
     * @dataProvider limitProvider
     */
    public function testPdoIbmDb2Limit($count, $offset, $expected)
    {
        $server = new Zend_Db_Adapter_Pdo_Ibm_Db2(null);
        $this->assertSame($expected, $server->limit('SELECT * FROM t ORDER BY id', $count, $offset));
    }

    public function testPdoIbmDb2LimitWithoutRows()
    {
        $server = new Zend_Db_Adapter_Pdo_Ibm_Db2(null);
        $this->assertSame('SELECT z1.* FROM (SELECT * FROM t) z1 WHERE 1 = 0', $server->limit('SELECT * FROM t', 0));
    }

    public function testDb2LimitRejectsInvalidCount()
    {
        $this->expectException(Zend_Db_Adapter_Db2_Exception::class);
        $this->_getDb2Adapter()->limit('SELECT * FROM t', 0);
    }

    public function testDb2LimitRejectsNegativeOffset()
    {
        $this->expectException(Zend_Db_Adapter_Db2_Exception::class);
        $this->_getDb2Adapter()->limit('SELECT * FROM t', 10, -1);
    }

    public function testPdoIbmDb2LimitRejectsNegativeOffset()
    {
        $this->expectException(Zend_Db_Adapter_Exception::class);
        (new Zend_Db_Adapter_Pdo_Ibm_Db2(null))->limit('SELECT * FROM t', 10, -1);
    }

    /**
     * @return Zend_Db_Adapter_Db2
     */
    protected function _getDb2Adapter()
    {
        if (!extension_loaded('ibm_db2')) {
            // the adapter uses constants of the extension
            $this->markTestSkipped('The ibm_db2 extension is not loaded');
        }

        return new Zend_Db_Adapter_Db2(['dbname' => 'test', 'username' => 'test', 'password' => 'test']);
    }
}
